"""Independent element-force/energy, finite-port and true-CAD-gap audit.
Does not invoke producer, its solver, skfem assembler or load-balancing helper.
"""
import sys,json,time,shutil
import numpy as np
from baseline_registry import ROOT,REPO,ref,sha,dump

def main():
 start=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');sources=[ROOT/'validation/integrated'/tag/'summary.json' for tag in sys.argv[2:]];docs=[json.loads(p.read_text()) for p in sources];candidate=docs[0]['candidate'];cad=json.loads((REPO/candidate['path']).read_text());assert all(sha(REPO/r['path'])==r['SHA256'] for r in cad['part_references'].values());dump(out/'inputs.json',dict(candidate=candidate,sources=[ref(p) for p in sources],verifier=ref(out/'verifier.py'),scope='Independent constant-strain tetra energy/internal forces; reconstruct each finite curved pressure port from retained quadrature. True-CAD nominal pin/hole gaps compared to conditional freebody displacement scale; finite pressure band is explicitly NOT contact equilibrium.'))
 results=[];geometry_results=[];mesh_comparisons=[];shape_comparisons=[]
 for sp,s in zip(sources,docs):
  assert s['candidate']==candidate;inp=json.loads((REPO/s['inputs']['path']).read_text());a=np.load(REPO/s['fields']['path']);p=a['points_mm'];t=a['tetra'];E=inp['conditional_E_MPa'];nu=inp['conditional_nu'];lam=E*nu/((1+nu)*(1-2*nu));mu=E/(2*(1+nu));dx=p[t[:,1:]]-p[t[:,0,None]];inv=np.linalg.inv(dx);V=abs(np.linalg.det(dx))/6;gr=np.concatenate([-inv.sum(2)[:,None,:],inv.transpose(0,2,1)],axis=1);journal=json.loads((REPO/s['finite_quadrature']['path']).read_text());geos=json.loads((REPO/inp['pin_holes']['path']).read_text());weights=a['clamp_weight_mm2'];ids=np.flatnonzero(weights)
  for r in s['results']:
   angle=r['angle_rad'];key=f'a{angle:g}';B=a[key+'_unit_loads_N'];U=a[key+'_unit_displacements_mm'];C=a[key+'_compliance_mm_N'];energies=[];force_errors=[]
   for j in range(4):
    u=U[:,j].reshape(-1,3);du=u[t[:,1:]]-u[t[:,0,None]];G=np.einsum('tij,tjk->tik',inv,du).transpose(0,2,1);eps=(G+G.transpose(0,2,1))/2;trace=np.trace(eps,axis1=1,axis2=2);sigma=2*mu*eps+lam*trace[:,None,None]*np.eye(3);energy=float(np.sum(V*(mu*np.sum(eps*eps,axis=(1,2))+.5*lam*trace**2)));internal=np.zeros_like(u);el_force=V[:,None,None]*np.einsum('tij,tkj->tki',sigma,gr)
    for k in range(4):np.add.at(internal,t[:,k],el_force[:,k])
    energies.append(energy);force_errors.append(float(abs(internal.ravel()-B[:,j]).max()))
   reconstructed=[];rawports=[];normal_gap_cases=[]
   reactions=np.array(r['conditional_Root_side_reaction_N']);u=(U@reactions).reshape(-1,3);wm=weights[ids]/weights[ids].sum();origin=wm@p[ids];Hpose=np.zeros((3*len(ids),6))
   for j,pt in enumerate(p[ids]-origin):Hpose[3*j:3*j+3,:3]=np.eye(3);Hpose[3*j:3*j+3,3:]=[[0,pt[2],-pt[1]],[-pt[2],0,pt[0]],[pt[1],-pt[0],0]]
   wp=np.repeat(wm,3);pose=np.linalg.solve((Hpose.T*wp)@Hpose,(Hpose.T*wp)@u[ids].ravel());rigid=pose[:3]+np.cross(pose[3:],p-origin);urel=u-rigid;common=r['conditional_common_port_motion_mm'];closure_bound=abs(common)+float(np.linalg.norm(urel,axis=1).max());maxb=0.;maxrecon=0.
   for port,g in enumerate(geos):
    f=np.zeros_like(p);qs=[q for q in journal if q['angle_rad']==angle and q['port']==port];gaps=[];areas=[]
    for q in qs:
     tr=np.array(q['nodes']);bc=np.array(q['barycentric']);pt=np.array(q['q_mm']);ar=q['area_mm2'];normal=np.array(q['normal']);ff=-normal*ar
     assert bc.min()>-1e-10 and abs(bc.sum()-1)<1e-10;maxb=max(maxb,float(max(0,-bc.min())));maxrecon=max(maxrecon,float(abs(bc@p[tr]-pt).max()));assert q['axial_interval_mm'][0]-1e-10<=pt[0]<=q['axial_interval_mm'][1]+1e-10
     for k,node in enumerate(tr):f[node]+=ff*bc[k]
     yc,zc=g['pin']['axis_point_mm'][1:];v=pt[1:]-[yc,zc];true=v/np.linalg.norm(v)*g['pin']['radius_mm'];gap=g['hole']['radius_mm']-np.linalg.norm(true+[g['clearance_mm'],0]);gaps.append(float(gap));areas.append(ar)
    f/=-f[:,1].sum();W=np.r_[f.sum(0),np.cross(p,f).sum(0)];M=np.zeros((6,3*len(ids)))
    for j,pt in enumerate(p[ids]):M[:3,3*j:3*j+3]=np.eye(3);M[3:,3*j:3*j+3]=[[0,-pt[2],pt[1]],[pt[2],0,-pt[0]],[-pt[1],pt[0],0]]
    ww=np.repeat(weights[ids],3);ret=ww*(M.T@np.linalg.solve((M*ww)@M.T,-W));f[ids]+=ret.reshape(-1,3);reconstructed.append(f.ravel());rawports.append(W.tolist());frac=float(np.sum(np.array(areas)[np.array(gaps)>closure_bound])/sum(areas));normal_gap_cases.append(dict(port=port,part=g['part'],actual_nominal_CAD_gap_range_mm=[min(gaps),max(gaps)],conditional_Root_motion_plus_port_closure_bound_mm=closure_bound,positive_pressure_area_fraction_exceeding_that_bound=frac,pressure_band_contact_equilibrium_rejected=frac>0,reason='Most prescribed pressure support remains at positive actual CAD gap even under this conditional displacement bound. True pressure width must be solved with compliant pin+hole geometry; pressure-shape witness cannot close contact.'))
   reconstructed=np.array(reconstructed).T;energy_error=max(abs(np.array(energies)-np.diag(C)/2)/np.maximum(abs(np.diag(C)/2),1e-30));loaderr=float(abs(reconstructed-B).max());rr=dict(source=ref(sp),angle_rad=angle,independent_tetra_energy_relative_error=float(energy_error),independent_internal_force_max_error_N=max(force_errors),independent_finite_load_reconstruction_error_N=loaderr,max_barycentric_position_error_mm=maxrecon,positive_compliance_eigenvalues=np.linalg.eigvalsh((B.T@U+U.T@B)/2).tolist(),raw_pin_wrenches_N_Nmm=rawports,actual_contact_gap_rejections=normal_gap_cases);results.append(rr)
  shape_comparisons.append(dict(source=ref(sp),angles_rad=[r['angle_rad'] for r in s['results']],relative_compliance_matrix_change=float(np.linalg.norm(np.array(s['results'][0]['compliance_mm_N'])-np.array(s['results'][1]['compliance_mm_N']))/np.linalg.norm(s['results'][1]['compliance_mm_N'])),maximum_reaction_fraction_total_change=float(np.max(abs(np.array(s['results'][0]['conditional_Root_side_reaction_N'])-np.array(s['results'][1]['conditional_Root_side_reaction_N'])))/s['results'][0]['conditional_total_source_reaction_N']),physical_split_qualified=False))
 for coarse,fine in zip(docs,docs[1:]):
  for c,f in zip(coarse['results'],fine['results']):
   C=np.array(c['compliance_mm_N']);F=np.array(f['compliance_mm_N']);relative=float(np.linalg.norm(C-F)/np.linalg.norm(F));motion=abs(c['conditional_common_port_motion_mm']/f['conditional_common_port_motion_mm']-1);reactions=float(np.max(abs(np.array(c['conditional_Root_side_reaction_N'])-np.array(f['conditional_Root_side_reaction_N'])))/f['conditional_total_source_reaction_N']);mesh_comparisons.append(dict(coarse_h_mm=coarse['h_mm'],fine_h_mm=fine['h_mm'],angle_rad=c['angle_rad'],relative_compliance_matrix_change=relative,relative_conditional_common_motion_change=motion,max_reaction_change_fraction_total=reactions,original_1percent_response_limit=.01,response_mesh_1percent_pass=bool(max(relative,motion,reactions)<.01),whole_system_convergence=False))
 checks=dict(independent_energy=all(r['independent_tetra_energy_relative_error']<1e-8 for r in results),independent_internal_forces=all(r['independent_internal_force_max_error_N']<1e-8 for r in results),independent_port_loads=all(r['independent_finite_load_reconstruction_error_N']<1e-10 and r['max_barycentric_position_error_mm']<1e-9 for r in results),all_pressure_band_false_contact_claims_rejected=all(g['pressure_band_contact_equilibrium_rejected'] for r in results for g in r['actual_contact_gap_rejections']))
 dump(out/'summary.json',dict(status='ACTUAL_P1_INDEPENDENT_ROOT_COMPLIANCE_AND_PRESSURE_GAP_REJECTION' if all(checks.values()) else 'ACTUAL_P1_ROOT_COMPLIANCE_INDEPENDENT_AUDIT_FAIL',candidate=candidate,inputs=ref(out/'inputs.json'),checks=checks,results=results,mesh_comparisons=mesh_comparisons,pressure_shape_sensitivities=shape_comparisons,elapsed_s=time.monotonic()-start,accepted_equilibria=0,newly_qualified_system_gate_ids=[],whole_system_release=False,limitations=['Element elastic-energy/force identities are local linear structure checks, NOT total system stored-energy closure or contact equilibrium.','Pressure shape is not solved. Finite-band ownweight sensitivity cannot be substituted for actual operating demand, upstream clamp/pin split, physical bore/thread law or product strength. Actual candidate78solids unchanged. Hardware NOT_MEASURED.']))
 print(json.dumps(dict(checks=checks,mesh_comparisons=mesh_comparisons,pressure_shape_sensitivities=shape_comparisons)));return 0 if all(checks.values()) else 2
if __name__=='__main__':sys.exit(main())
